// This file is generated by AI.

// 磁盘变更同步的判据 (纯函数) —— 决策表必须能在这里被钉死。
//
// 这些用例覆盖的是"哪些情况**不该**弹对话框": 假冲突比漏判更容易被忽略 —— 用户会在一次
// 自动保存之后被告知"文件被外部修改了", 而对话框里两个选项其实没有区别。

import { describe, expect, it } from 'vitest';

import {
  affectedDocumentPaths,
  contentHash,
  decideDiskAction,
  normalizeContent,
  pathKey,
  previewOf,
} from '../src/editor/disk-state';

const base = contentHash('base\ndisk\n');
const edited = contentHash('edited\nin editor\n');
const external = contentHash('changed\nby someone else\n');

describe('decideDiskAction', () => {
  it('磁盘与基准相同: 忽略 (变的是编辑器那一侧)', () => {
    expect(decideDiskAction({ diskHash: base, baseHash: base, memHash: edited, dirty: true })).toBe('ignore');
    expect(decideDiskAction({ diskHash: base, baseHash: base, memHash: base, dirty: false })).toBe('ignore');
  });

  it('磁盘与编辑器内容一致: 只对齐基准 (可能是我们自己的写盘)', () => {
    // 脏文档也一样: 内容相同就没有任何需要裁决的东西
    expect(decideDiskAction({ diskHash: edited, baseHash: base, memHash: edited, dirty: true })).toBe('adopt');
    expect(decideDiskAction({ diskHash: edited, baseHash: base, memHash: edited, dirty: false })).toBe('adopt');
  });

  it('磁盘既不是基准也不是编辑器内容: 干净文档直接重读', () => {
    expect(decideDiskAction({ diskHash: external, baseHash: base, memHash: base, dirty: false })).toBe('reload');
  });

  it('磁盘既不是基准也不是编辑器内容: 脏文档进入裁决', () => {
    expect(decideDiskAction({ diskHash: external, baseHash: base, memHash: edited, dirty: true })).toBe('conflict');
  });

  it('没有基准时按"磁盘与编辑器不同"处理 (刚打开就已被外部改过)', () => {
    expect(decideDiskAction({ diskHash: external, baseHash: undefined, memHash: base, dirty: false })).toBe('reload');
    expect(decideDiskAction({ diskHash: external, baseHash: undefined, memHash: edited, dirty: true })).toBe(
      'conflict'
    );
  });
});

describe('contentHash / normalizeContent', () => {
  it('换行归一化之后才算哈希 (CRLF 与 LF 是同一份内容)', () => {
    expect(contentHash('a\r\nb\r\nc')).toBe(contentHash('a\nb\nc'));
    expect(normalizeContent('a\r\nb')).toBe('a\nb');
  });

  it('不同内容得到不同哈希, 且总是非空字符串', () => {
    expect(contentHash('a')).not.toBe(contentHash('b'));
    expect(typeof contentHash('')).toBe('string');
  });
});

describe('pathKey', () => {
  it('统一分隔符与大小写', () => {
    expect(pathKey('C:\\Proj\\game\\scene\\A.txt')).toBe(pathKey('c:/proj/game/scene/a.txt'));
  });
});

describe('affectedDocumentPaths', () => {
  const documents = [{ path: 'C:\\Proj\\game\\scene\\a.txt' }, { path: 'C:\\Proj\\game\\config.txt' }];

  it('只挑出真正变化的文档 (大小写与分隔符都不敏感)', () => {
    expect(affectedDocumentPaths(documents, ['c:/proj/game/scene/A.txt'])).toEqual([documents[0]!.path]);
  });

  it('没命中的路径不产生任何结果', () => {
    expect(affectedDocumentPaths(documents, ['C:/Proj/game/vocal/narration/x.wav'])).toEqual([]);
  });

  it('事件没带路径时检查全部文档 (宁可多读一遍)', () => {
    expect(affectedDocumentPaths(documents, [])).toEqual([documents[0]!.path, documents[1]!.path]);
  });
});

describe('previewOf', () => {
  it('只取开头若干行, CRLF 也能切', () => {
    const text = Array.from({ length: 30 }, (_, index) => `line ${index + 1}`).join('\r\n');
    const preview = previewOf(text, 3);
    expect(preview).toBe('line 1\nline 2\nline 3');
  });

  it('内容不足时原样返回', () => {
    expect(previewOf('only line')).toBe('only line');
  });
});
